]

DATASET_URL = ""

OUTPUT_DIR = Path("app")
OUTPUT_DIR.mkdir(exist_ok=True)

data_lock = Lock()
translation_cache = {}

class APIKeyRotator:
    def __init__(self, keys, models):
        self.keys = keys
        self.models = models
        self.key_index = 0
        self.model_index = 0
        self.lock = Lock()

    def get_next(self):
        with self.lock:
            key = self.keys[self.key_index]
            model = self.models[self.model_index]

            self.model_index = (self.model_index + 1) % len(self.models)
            if self.model_index == 0:
                self.key_index = (self.key_index + 1) % len(self.keys)

            return key, model

rotator = APIKeyRotator(CEREBRAS_API_KEYS, MODELS)

def download_dataset():
    logger.info(f"Downloading dataset from {DATASET_URL}")

    try:
        response = requests.get(DATASET_URL, timeout=120)
        response.raise_for_status()

        dataset = []
        for line in response.text.strip().split('\n'):
            if line.strip():
                try:
                    dataset.append(json.loads(line))
                except:
                    continue

        logger.info(f"Successfully downloaded {len(dataset)} entries")
        return dataset

    except Exception as e:
        logger.error(f"Failed to download dataset: {e}")
        return [
            {
                "id": i,
                "question": f"Sample question {i} for advanced AI training",
                "answer": f"Comprehensive answer {i} with detailed explanation",
                "context": f"Additional context {i} for verification purposes"
            }
            for i in range(100)
        ]

def translate_text_batch(texts, target_language, api_key, model_info):
    if not texts or not any(texts):
        return [""] * len(texts)

    combined_text = "\n###SEPARATOR###\n".join([t if t else "" for t in texts])

    prompt = f"""Translate each text segment to {target_language}. Keep the ###SEPARATOR### markers unchanged. Output ONLY translations separated by ###SEPARATOR###, no other text.

{combined_text}"""

    payload = {
        "model": model_info["name"],
        "messages": [
            {"role": "system", "content": f"You are a professional translator to {target_language}. Output only translations."},
            {"role": "user", "content": prompt}
        ],
        "temperature": 0.1,
        "max_tokens": model_info["max_tokens"],
        "top_p": 0.95
    }

    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json"
    }

    for attempt in range(3):
        try:
            response = requests.post(
                CEREBRAS_BASE_URL,
                headers=headers,
                json=payload,
                timeout=30
            )

            if response.status_code == 200:
                result = response.json()
                translation = result["choices"][0]["message"]["content"].strip()

                translations = translation.split("###SEPARATOR###")

                if len(translations) == len(texts):
                    return [t.strip() for t in translations]
                else:
                    return translate_text_batch(texts, target_language, api_key, model_info) if attempt < 2 else texts

            elif response.status_code == 429:
                time.sleep(0.5)
                continue

            else:
                logger.warning(f"API error {response.status_code}")
                time.sleep(0.2)
                continue

        except Exception as e:
            logger.error(f"Translation error: {e}")
            if attempt < 2:
                time.sleep(0.3)
            else:
                return texts

    return texts

def translate_entry_batch(entries, language):
    api_key, model_info = rotator.get_next()

    questions = [e.get("question", "") for e in entries]
    answers = [e.get("answer", "") for e in entries]
    contexts = [e.get("context", "") for e in entries]

    translated_questions = translate_text_batch(questions, language, api_key, model_info)
    translated_answers = translate_text_batch(answers, language, api_key, model_info)
    translated_contexts = translate_text_batch(contexts, language, api_key, model_info)

    results = []
    for i, entry in enumerate(entries):
        results.append({
            "id": entry.get("id"),
            "language": language,
            "question": translated_questions[i],
            "answer": translated_answers[i],
            "context": translated_contexts[i]
        })

    return results

def process_language_batch(language, dataset):
    logger.info(f"Processing {language}")

    all_translated = []
    batch_size = 5

    for i in range(0, len(dataset), batch_size):
        batch = dataset[i:i+batch_size]

        try:
            translated_batch = translate_entry_batch(batch, language)
            all_translated.extend(translated_batch)

            time.sleep(0.05)

        except Exception as e:
            logger.error(f"Batch error for {language}: {e}")
            for entry in batch:
                all_translated.append({
                    "id": entry.get("id"),
                    "language": language,
                    "question": entry.get("question", ""),
                    "answer": entry.get("answer", ""),
                    "context": entry.get("context", "")
                })

    logger.info(f"Completed {language}: {len(all_translated)} entries")
    return language, all_translated

def main():
    logger.info("=" * 80)
    logger.info("JAIDE Ultra-Fast Multilingual Dataset Translation")
    logger.info("=" * 80)

    dataset = download_dataset()
    logger.info(f"Dataset loaded: {len(dataset)} entries")

    all_translations = {}
    max_workers = 90

    start_time = time.time()

    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = {
            executor.submit(process_language_batch, lang, dataset): lang
            for lang in TARGET_LANGUAGES
        }

        for future in as_completed(futures):
            language = futures[future]

            try:
                lang, translated_data = future.result()
                all_translations[lang] = translated_data

            except Exception as e:
                logger.error(f"Failed {language}: {e}")
                all_translations[language] = []

    elapsed = time.time() - start_time
    logger.info(f"Translation completed in {elapsed:.2f} seconds")

    final_dataset = []

    all_ids = set()
    for lang_data in all_translations.values():
        for entry in lang_data:
            all_ids.add(entry.get("id"))

    for entry_id in sorted(all_ids):
        merged_entry = {
            "id": entry_id,
            "translations": {}
        }

        for language, lang_data in all_translations.items():
            for entry in lang_data:
                if entry.get("id") == entry_id:
                    merged_entry["translations"][language] = {
                        "question": entry.get("question", ""),
                        "answer": entry.get("answer", ""),
                        "context": entry.get("context", "")
                    }
                    break

        final_dataset.append(merged_entry)

    final_output = OUTPUT_DIR / "jaide_multilingual_dataset_complete.json"

    with open(final_output, 'w', encoding='utf-8') as f:
        json.dump(final_dataset, f, ensure_ascii=False, indent=2)

    logger.info(f"Final dataset saved: {final_output}")
    logger.info(f"Total entries: {len(final_dataset)}")
    logger.info(f"Languages: {len(TARGET_LANGUAGES)}")
    logger.info(f"Total time: {elapsed:.2f} seconds")
    logger.info("=" * 80)
    logger.info("JAIDE dataset ready for training")
    logger.info("=" * 80)

if __name__ == "__main__":
    main()
